import type { Profile, WorldSummary } from "./types";

const KEY = "eo2.profile";

const DEMO_WORLD: WorldSummary = {
  id: "demo-bobo",
  title: "Bobo Doll Experiment",
  topic: "IB Psychology — Bandura, Ross & Ross (1961)",
  creator: "EduOasis",
  createdAt: Date.now() - 3 * 86400_000,
  lastVisitedAt: Date.now() - 86400_000,
  halfLifeH: 48, // one day since the last visit → recall 71%
  streak: 1, // review every 2 days → lifespan 50%
  recall: 0.71,
  gameType: "rpg-experiment",
};

// Generated by our own pipeline from Loftus & Palmer notes (src/content/samples/loftus.world.json)
const SAMPLE_LOFTUS: WorldSummary = {
  id: "sample-loftus",
  title: "Loftus & Palmer (1974)",
  topic: "IB Psychology — reconstructive memory & leading questions",
  creator: "EduOasis",
  createdAt: Date.now() - 86400_000,
  lastVisitedAt: Date.now() - 3 * 3600_000,
  halfLifeH: 24,
  streak: 0,
  recall: 0.92,
  gameType: "explore-collect",
};

export function defaultProfile(): Profile {
  return { name: "Learner", generationsLeft: 2, worlds: [DEMO_WORLD, SAMPLE_LOFTUS, null] };
}

export function loadProfile(): Profile {
  try {
    const raw = localStorage.getItem(KEY);
    if (raw) return JSON.parse(raw) as Profile;
  } catch {}
  return defaultProfile();
}

export function saveProfile(p: Profile) {
  try {
    localStorage.setItem(KEY, JSON.stringify(p));
  } catch {}
}
